mat2 rot(float a) { float s = sin(a), c = cos(a); return mat2(c, -s, s, c); }
float map(vec3 p) {
  p.z += time * 0.5;
  float g = dot(sin(p * 2.5), cos(p.zxy * 2.5));
  return abs(g) - 0.15;
}
shader_body {
  vec2 p = (uv - 0.5) * vec2(aspect.x, 1.0) * 2.0;
  vec3 ro = vec3(0.0, 0.0, -1.0);
  vec3 rd = normalize(vec3(p, 1.4));
  float t = 0.0;
  for (int i = 0; i < 48; i++) {
    float d = map(ro + rd * t);
    if (d < 0.003 || t > 10.0) break;
    t += d * 0.75;
  }
  vec3 col = vec3(0.03, 0.01, 0.05);
  if (t < 10.0) {
    vec3 pos = ro + rd * t;
    vec3 coral = 0.5 + 0.5 * sin(vec3(0.0, 1.5, 3.0) + pos.z * 2.0);
    float fog = 1.0 / (1.0 + t * t * 0.04);
    col = coral * fog * 1.5;
  }
  ret = col;
}
